<script setup lang="ts">
import {computed,watch} from 'vue'
const props=defineProps<{form:Record<string,any>,template?:Record<string,any>}>()
const names:Record<string,string>={tcp:'TCP / 原生协议',ws:'WebSocket',grpc:'gRPC',http:'HTTP / HTTP2',httpupgrade:'HTTPUpgrade',xhttp:'XHTTP',kcp:'mKCP',quic:'QUIC / UDP'}
const layers=computed(()=>props.template?.layers?.[props.form.engine]??[{transport:'tcp',security_modes:['tls']}])
const modes=computed(()=>layers.value.find((l:any)=>l.transport===props.form.transport)?.security_modes??[])
function sync(){if(!props.template?.layers)return;if(!layers.value.some((l:any)=>l.transport===props.form.transport))props.form.transport=layers.value[0]?.transport??'tcp';if(!modes.value.includes(props.form.tls_mode))props.form.tls_mode=modes.value[0]??'none';if(['ws','httpupgrade','http','xhttp'].includes(props.form.transport)&&!props.form.path)props.form.path='/proxy';if(props.form.transport==='grpc'&&!props.form.service_name)props.form.service_name='starhub'}
watch(()=>[props.form.engine,props.form.kind,props.form.transport,props.template],sync,{immediate:true})
</script>
<template><fieldset class="protocol-layers"><legend>协议 → 传输方式 → 传输安全</legend><div class="fields"><label>传输方式<select v-model="form.transport" :disabled="layers.length===1"><option v-for="l in layers" :key="l.transport" :value="l.transport">{{names[l.transport]||l.transport}}</option></select></label><label>传输安全<select v-model="form.tls_mode" :disabled="modes.length===1"><option v-for="s in modes" :key="s" :value="s">{{s==='tls'?'TLS · 需要匹配证书':s==='reality'?'REALITY · 密钥与握手目标':'无外层 TLS · 协议自身认证/加密'}}</option></select></label><label v-if="['ws','http','httpupgrade','xhttp'].includes(form.transport)">传输路径<input v-model="form.path" required placeholder="/proxy"></label><label v-if="form.transport==='grpc'">gRPC 服务名<input v-model="form.service_name" required placeholder="starhub"></label><label v-if="['ws','http','httpupgrade','xhttp'].includes(form.transport)">Host（可选）<input v-model="form.ws_host" placeholder="默认连接地址"></label></div><p class="form-note">只列出该内核已适配的组合。QUIC 协议内置 TLS；REALITY 不能替代普通 TLS 证书。新传输和扩展协议需要 Agent 0.13。XHTTP/mKCP 导出使用 Xray JSON；HTTPUpgrade 使用 sing-box/Xray 格式。</p></fieldset></template>
<style scoped>.protocol-layers{margin:20px 0;border:1px solid var(--border);border-radius:14px;padding:18px}.protocol-layers legend{padding:0 8px;color:var(--accent)}.protocol-layers .fields{margin-top:8px}@media(max-width:600px){.protocol-layers{padding:12px}}</style>
